import type { AppOrElementRef, AutomationRef, FieldRef, RecordIdentityRef } from "../../catalog/index.js";
import type { WorkflowFieldType } from "../shared/types/field-types.js";
import type { Filter } from "../shared/filters/types.js";
export type WidgetButtonType = "INLINE" | "PRIMARY" | "SECONDARY";
export interface WidgetButtonStyle {
    readonly buttonType: WidgetButtonType;
    readonly color?: string;
    readonly icon?: string;
    readonly fullWidth?: boolean;
}
/**
 * Lists matching records from `target` on this object's record page.
 *
 * The widget only names the target and display columns. The platform finds
 * rows through an authored `relationships[]` join on **this** app/element
 * whose columns join comparable stored values (TEXT→TEXT, or this object's
 * `relationField` → related title/id). Do not join system `"id"` (HANDLE)
 * to a child `relationField`. A child `relationField` / dynamic dropdown
 * with `autoRelate` stores an instance link; it does not populate this widget.
 */
export interface RelatedRecordsWidget<Target extends AppOrElementRef = AppOrElementRef> {
    readonly type: "relatedRecords";
    readonly name: string;
    readonly target: Target;
    readonly columns?: readonly (FieldRef | RecordIdentityRef<Target>)[];
    readonly rows?: number;
}
export interface LinkRecordsWidget<Target extends AppOrElementRef = AppOrElementRef> extends WidgetButtonStyle {
    readonly type: "linkRecords";
    readonly name: string;
    readonly target: Target;
    readonly columns?: readonly (FieldRef | RecordIdentityRef<Target>)[];
    readonly rows?: number;
    /** Provider-native filter payload. */
    readonly filter?: Filter;
}
export interface CreateRecordWidget extends WidgetButtonStyle {
    readonly type: "createRecord";
    readonly name: string;
    readonly target: AppOrElementRef;
}
interface RunAutomationWidgetParameterBase {
    readonly name: string;
    readonly fieldType: WorkflowFieldType;
    readonly multiple?: boolean;
    readonly required?: boolean;
}
export type RunAutomationWidgetParameter = RunAutomationWidgetParameterBase & ({
    /** Read this field from the current record. Mutually exclusive with `value`. */
    readonly field: FieldRef;
    readonly value?: never;
} | {
    /** Static value; supports the provider's `{{field-id}}` interpolation syntax. */
    readonly field?: never;
    readonly value: string;
});
export interface RunAutomationWidget extends WidgetButtonStyle {
    readonly type: "runAutomation";
    readonly name: string;
    readonly automation: AutomationRef;
    readonly parameters?: readonly RunAutomationWidgetParameter[];
}
/** One record-layout display widget (`elementum_widget`). */
export type AppWidget = RelatedRecordsWidget | LinkRecordsWidget | CreateRecordWidget | RunAutomationWidget;
export {};
